@Test
public void testSums() {
    assertEquals(new Long(1775L), CombineFn.SUM_LONGS().combine(ImmutableList.of(29L, 17L, 1729L)));
    assertEquals(new Integer(1775), CombineFn.SUM_INTS().combine(ImmutableList.of(29, 17, 1729)));
    assertEquals(new Float(1775.0f), CombineFn.SUM_FLOATS().combine(ImmutableList.of(29f, 17f, 1729f)));
    assertEquals(new Double(1775.0), CombineFn.SUM_DOUBLES().combine(ImmutableList.of(29.0, 17.0, 1729.0)));
}

